#include "HierarchyMachine.h"
#include <stdio.h>
static int Check(HierarchyData*d,int a,int b,int c){return(d->count>=3&&d->log[0]==a&&d->log[1]==b&&d->log[2]==c)?0:1;}
int main(void){ESCX_StateMachine m;HierarchyData d;ESCX_BYTE_T bits[ESCX_ACTIVE_BYTES(HierarchyMachine_STATE_COUNT)];d.count=0;HierarchyMachine_Init(&m,&d,bits,(ESCX_BYTE_T)sizeof(bits),(ESCX_StartTimerFunction)0,(ESCX_CancelTimerFunction)0);if(ESCX_StateMachineStart(&m)!=ESCX_STATUS_PROCESSED)return 1;if(Check(&d,1,2,3))return 2;if(!ESCX_StateMachineIsInState(&m,HM_Root)||!ESCX_StateMachineIsInState(&m,HM_Parent)||!ESCX_StateMachineIsInState(&m,HM_ChildA))return 3;if(ESCX_StateMachineSend(&m,HM_Next,(void*)0)!=ESCX_STATUS_PROCESSED)return 4;if(!ESCX_StateMachineIsInState(&m,HM_ChildB)||ESCX_StateMachineIsInState(&m,HM_ChildA))return 5;if(ESCX_StateMachineSend(&m,HM_Targetless,(void*)0)!=ESCX_STATUS_PROCESSED)return 6;if(!ESCX_StateMachineIsInState(&m,HM_ChildB))return 7;if(ESCX_StateMachineSend(&m,HM_OutsideEvent,(void*)0)!=ESCX_STATUS_PROCESSED)return 8;if(!ESCX_StateMachineIsInState(&m,HM_Outside)||ESCX_StateMachineIsInState(&m,HM_Parent))return 9;printf("hierarchy tests passed\n");return 0;}
